(function(){"use strict";
const API="/api",TOKEN="cs360_portal_colaborador_token";
const labels={RASCUNHO:"Precisa da minha ação",PENDENTE_APROVACAO:"Aguardando aprovação",APROVADO:"Aprovada",EM_ATENDIMENTO:"Em atendimento",CONCLUIDO:"Concluída",REJEITADO:"Precisa da minha ação",CANCELADO:"Cancelada"};
const groups={progress:["APROVADO","EM_ATENDIMENTO"],approval:["PENDENTE_APROVACAO"],action:["RASCUNHO","REJEITADO"],done:["CONCLUIDO"]};
const icons={plane:'<path d="m2 16 8-3 3-9 2-2 1 1-2 9 6-2 2 2-8 4-2 6-2-2v-5l-4 1Z"/>',car:'<path d="M5 17h14l-1-7-2-3H8l-2 3-1 7Z"/><path d="M3 13h18M7 17v3M17 17v3"/>',box:'<path d="m3 7 9-4 9 4-9 4-9-4Z"/><path d="M3 7v10l9 4 9-4V7M12 11v10"/>',parking:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M9 17V7h4a3 3 0 0 1 0 6H9"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/>',print:'<path d="M7 8V3h10v5M7 17H5a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><path d="M7 14h10v7H7z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6M10 7v6M7 10h6"/>',key:'<circle cx="8" cy="15" r="4"/><path d="m11 12 9-9M16 7l2 2M14 9l2 2"/>',shield:'<path d="M12 3 4 6v5c0 5 3 8 8 10 5-2 8-5 8-10V6l-8-3Z"/><path d="m8 12 3 3 5-6"/>',document:'<path d="M6 3h9l4 4v14H6zM14 3v5h5"/><circle cx="11" cy="13" r="3"/><path d="m13 15 2 2"/>'};
const services=[
{id:"viagem",name:"Viagens",group:"Deslocamentos",description:"Passagens, hospedagem e deslocamentos corporativos.",keywords:"avião passagem hotel hospedagem deslocamento",icon:"plane"},{id:"mobilidade",name:"Mobilidade",group:"Deslocamentos",description:"Acessos e solicitações de mobilidade corporativa.",keywords:"carro uber táxi transporte deslocamento",icon:"car"},{id:"estacionamento",name:"Estacionamento",group:"Deslocamentos",description:"Solicitações relacionadas a estacionamento e veículos.",keywords:"vaga carro veículo garagem",icon:"parking"},
{id:"entregas",name:"Entregas",group:"Envios e apoio",description:"Envio e movimentação de volumes e encomendas.",keywords:"pacote caixa volume encomenda envio",icon:"box"},{id:"correios",name:"Correios",group:"Envios e apoio",description:"Postagens e serviços de correspondência.",keywords:"carta sedex postagem correspondência pacote",icon:"mail"},{id:"xerox",name:"Xerox / Impressões",group:"Envios e apoio",description:"Cópias, impressões e serviços gráficos.",keywords:"impressão imprimir cópia gráfica papel xerox",icon:"print"},
{id:"achados_perdidos",name:"Achados e Perdidos",group:"Serviços institucionais",description:"Registre um item perdido ou encontrado.",keywords:"perdi encontrei objeto item busca",icon:"search"},{id:"liberacao_acesso",name:"Acessos",group:"Serviços institucionais",description:"Acesso especial ou comunicação de perda de acesso.",keywords:"chave crachá badge liberação entrada",icon:"key"},{id:"autorizacao_excepcional",name:"Autorizações Excepcionais",group:"Serviços institucionais",description:"Solicitações fora do fluxo padrão.",keywords:"exceção especial aprovação autorização",icon:"shield",badge:"FLUXO DEMONSTRATIVO"},{id:"investigacao_ocorrencia",name:"Investigação de Ocorrência",group:"Serviços institucionais",description:"Fluxo identificado no sistema atual; formulário ainda pendente de mapeamento.",keywords:"ocorrência investigação incidente documento",icon:"document",badge:"EM LEVANTAMENTO",disabled:true}];
const extraServiceNames={transporte:"Transporte interno",solicitacao_imagens:"Solicitação de imagens"};
const servicePages={viagem:"portal-colaborador-nova-solicitacao.html?service=viagem",mobilidade:"portal-colaborador-nova-solicitacao.html?service=mobilidade",estacionamento:"portal-colaborador-nova-solicitacao.html?service=estacionamento",entregas:"portal-colaborador-nova-solicitacao.html?service=entregas",correios:"portal-colaborador-nova-solicitacao.html?service=correios",xerox:"portal-colaborador-nova-solicitacao.html?service=xerox",achados_perdidos:"portal-colaborador-nova-solicitacao.html?service=achados_perdidos",autorizacao_excepcional:"portal-colaborador-nova-solicitacao.html?service=autorizacao_excepcional"};
const recentServiceTypes=new Set(["viagem","mobilidade","entregas","estacionamento","correios","xerox","achados_perdidos","liberacao_acesso"]);
let profile=null,all=[],activeGroup=null;
const $=id=>document.getElementById(id),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),norm=v=>String(v).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase(),svg=n=>`<svg viewBox="0 0 24 24">${icons[n]}</svg>`;
async function api(path,options={}){const response=await fetch(API+path,{...options,headers:{"Content-Type":"application/json",...(localStorage.getItem(TOKEN)?{Authorization:`Bearer ${localStorage.getItem(TOKEN)}`}:{})}}),body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error?.message||"Falha na API");return body}
async function auth(){const login=await api("/auth/login",{method:"POST",body:JSON.stringify({email:"carlos.andrade@ficticio.org"})});localStorage.setItem(TOKEN,login.data.token);profile=(await api("/auth/employee-profile")).data;$("welcome").textContent=`Olá, ${profile.nome}. O que você precisa?`;$("profile-name").textContent=profile.nome;$("profile-summary-line").textContent=`${profile.departamento} · ${profile.centroCusto}`;$("profile").innerHTML=[["Matrícula",profile.matricula],["Nome",profile.nome],["E-mail",profile.email],["Cargo",profile.cargo],["Departamento",profile.departamento],["Centro de custo",profile.centroCusto],["Gestor",profile.gestor]].map(([k,v])=>`<div class="profile-item"><small>${k}</small><b>${esc(v)}</b><span title="Preenchido automaticamente">🔒</span></div>`).join("")}
function card(s){const content=`${s.badge?`<span class="service-badge">${s.badge}</span>`:""}<span class="service-icon">${svg(s.icon)}</span><h3>${s.name}</h3><p>${s.description}</p>${s.disabled?'<span class="disabled-action">Indisponível no protótipo</span>':'<span class="card-action">Solicitar <span>→</span></span>'}`;if(s.disabled)return `<article class="service-card disabled" data-catalog-service="${s.id}" aria-disabled="true">${content}</article>`;if(s.id==="liberacao_acesso")return `<button type="button" class="service-card" data-catalog-service="${s.id}" aria-haspopup="dialog">${content}</button>`;return `<a class="service-card" data-catalog-service="${s.id}" href="${servicePages[s.id]}">${content}</a>`}
function renderCatalog(q=""){const term=norm(q.trim()),filtered=services.filter(s=>!term||norm(`${s.name} ${s.description} ${s.keywords}`).includes(term));$("catalog").innerHTML=[...new Set(services.map(s=>s.group))].map(g=>{const items=filtered.filter(s=>s.group===g);return items.length?`<section class="catalog-group"><h3>${g}</h3><div class="cards">${items.map(card).join("")}</div></section>`:""}).join("");$("catalog-empty").hidden=!!filtered.length;document.querySelectorAll("a[data-catalog-service]").forEach(link=>link.onclick=()=>localStorage.setItem("cs360_assistant_context",JSON.stringify({role:"COLABORADOR",currentPage:"portal-colaborador",currentService:link.dataset.catalogService})));const accessCard=document.querySelector('[data-catalog-service="liberacao_acesso"]');if(accessCard)accessCard.onclick=()=>accessModal(true)}
function setupCatalog(){const enabled=services.filter(s=>!s.disabled),options='<option value="">Todos os serviços</option>'+enabled.map(s=>`<option value="${s.id}">${s.name}</option>`).join("");$("service").innerHTML=options.replace("Todos os serviços","Selecione");$("filter-service").innerHTML=options;renderCatalog()}
function openService(id){show("new");$("service").value=id;setAssistant(id,false)}
const match=(x,g)=>!g||groups[g]?.includes(x.status),serviceName=id=>services.find(s=>s.id===id)?.name||extraServiceNames[id]||id,format=v=>{const d=new Date(String(v).replace(" ","T"));return isNaN(d)?"—":new Intl.DateTimeFormat("pt-BR").format(d)};
function updateHome(){$("request-total").textContent=`${all.length} solicitações no período`;$('in-progress').textContent=all.filter(x=>match(x,"progress")).length;$('waiting-approval').textContent=all.filter(x=>match(x,"approval")).length;const actionCount=all.filter(x=>match(x,"action")).length;$('needs-action').textContent=actionCount;document.querySelector('[data-status-group="action"]').classList.toggle("has-action",actionCount>0);$('completed').textContent=all.filter(x=>match(x,"done")).length;const recent=[...all].filter(x=>recentServiceTypes.has(x.serviceType)).sort((a,b)=>new Date(b.createdAt.replace(" ","T"))-new Date(a.createdAt.replace(" ","T"))).slice(0,4);$("recent-requests").innerHTML=recent.length?recent.map(x=>`<button class="recent-row" data-request="${esc(x.id)}"><b>${esc(x.id)}</b><span>${esc(serviceName(x.serviceType))}</span><span class="badge status-${x.status}">${esc(labels[x.status]||x.status)}</span><time>${format(x.createdAt)}</time><span class="row-arrow">→</span></button>`).join(""):'<div class="empty">Você ainda não possui solicitações.</div>';bindRows()}
async function load(){all=(await api("/requests")).data;const statuses=[...new Set(all.map(x=>x.status))];$("filter-status").innerHTML='<option value="">Todos os status</option>'+statuses.map(x=>`<option value="${x}">${labels[x]||x}</option>`).join("");updateHome();renderRequests()}
function renderRequests(){const s=$("filter-service").value,st=$("filter-status").value,q=norm($("filter-search").value),days=+$("filter-period").value,rows=all.filter(x=>(!s||x.serviceType===s)&&(!st||x.status===st)&&match(x,activeGroup)&&(!q||norm(`${x.id} ${x.title}`).includes(q))&&(!days||(Date.now()-new Date(x.createdAt.replace(" ","T")))/864e5<=days));$("requests").innerHTML=rows.length?rows.map(x=>`<button class="request-row" data-request="${esc(x.id)}"><b>${esc(x.id)}</b><span>${esc(x.title)}</span><span>${esc(serviceName(x.serviceType))}</span><span class="badge status-${x.status}">${esc(labels[x.status]||x.status)}</span></button>`).join(""):'<div class="empty">Nenhuma solicitação encontrada.</div>';bindRows()}
function bindRows(){document.querySelectorAll("[data-request]").forEach(r=>r.onclick=()=>{show("requests");detail(r.dataset.request)})}
async function detail(id){try{const x=(await api("/requests/"+encodeURIComponent(id))).data;$("requests").innerHTML=`<article class="request-detail"><button class="link-button" data-close-detail>← Voltar</button><h2>${esc(x.id)} · ${esc(x.title)}</h2><p><span class="badge status-${x.status}">${esc(labels[x.status]||x.status)}</span></p><p>${esc(x.details?.description||x.details?.reason||"Sem descrição adicional.")}</p><h3>Histórico</h3><div class="timeline">${x.history.map(h=>`<div><b>${esc(h.action)}</b><br><small>${esc(h.date)}</small></div>`).join("")}</div></article>`;document.querySelector("[data-close-detail]").onclick=renderRequests}catch(e){toast(e.message)}}
function show(name){document.querySelectorAll(".view").forEach(x=>x.hidden=x.id!==`view-${name}`);document.querySelectorAll("[data-view]").forEach(x=>x.classList.toggle("active",x.dataset.view===name));if(name==="requests")renderRequests();scrollTo({top:0,behavior:"smooth"})}
function setAssistant(id=null,visible=true){const a=$("assistant"),s=services.find(x=>x.id===id);a.dataset.role="COLABORADOR";a.dataset.currentPage="portal-colaborador";a.dataset.currentService=id||"";$("assistant-context").textContent=s?`Portal do Colaborador · ${s.name}`:"Portal do Colaborador";if(visible)a.hidden=false}
function modal(open){$("profile-modal").hidden=!open;$("profile-open").setAttribute("aria-expanded",String(open))}
function accessModal(open){$("access-modal").hidden=!open;if(open)setTimeout(()=>$("access-close").focus(),0)}
function toast(t){const e=document.createElement("div");e.className="toast";e.textContent=t;document.body.append(e);setTimeout(()=>e.remove(),3200)}
function offline(e){$("request-total").textContent="Dados indisponíveis";document.querySelectorAll(".stat strong").forEach(x=>x.textContent="—");$("recent-requests").innerHTML='<div class="empty error-state"><b>Não foi possível carregar suas solicitações.</b><span>Verifique a conexão e tente novamente.</span><button class="btn secondary" id="retry-load">Tentar novamente</button></div>';$("retry-load").onclick=init;toast(e.message||"API indisponível")}
document.querySelectorAll("[data-view]").forEach(x=>x.onclick=()=>show(x.dataset.view));document.querySelectorAll("[data-status-group]").forEach(x=>x.onclick=()=>{activeGroup=x.dataset.statusGroup;$("filter-status").value="";show("requests")});["filter-service","filter-status","filter-period"].forEach(id=>$(id).onchange=()=>{activeGroup=null;renderRequests()});$("filter-search").oninput=()=>{activeGroup=null;renderRequests()};$("service-search").oninput=e=>renderCatalog(e.target.value);$("theme").onclick=()=>{const t=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=t;localStorage.setItem("cs360_theme",t)};["assistant-open","assistant-inline"].forEach(id=>$(id).onclick=()=>setAssistant());$("assistant-close").onclick=()=>$("assistant").hidden=true;$("profile-open").onclick=()=>modal(true);$("profile-close").onclick=()=>modal(false);$("profile-modal").onclick=e=>{if(e.target.id==="profile-modal")modal(false)};$("access-close").onclick=()=>accessModal(false);$("access-modal").onclick=e=>{if(e.target.id==="access-modal")accessModal(false)};document.onkeydown=e=>{if(e.key==="Escape"){modal(false);accessModal(false);$("assistant").hidden=true}};
$("request-form").onsubmit=async e=>{e.preventDefault();try{const created=await api("/requests",{method:"POST",body:JSON.stringify({serviceType:$("service").value,title:$("title").value,requesterId:profile.employeeId,requesterName:profile.nome,costCenter:profile.centroCusto,details:{description:$("description").value,periodFrom:$("from").value,periodTo:$("to").value,employeeFieldsSource:"EmployeeProfile"},urgent:false})});await api(`/requests/${created.data.id}/submit`,{method:"PUT",body:"{}"});e.target.reset();toast("Solicitação enviada com sucesso.");await load();show("requests")}catch(error){toast(error.message)}};
async function init(){try{await auth();await load();const params=new URLSearchParams(location.search);if(params.get("view")==="requests"){show("requests");if(params.get("request"))await detail(params.get("request"))}}catch(e){offline(e)}}document.documentElement.dataset.theme=localStorage.getItem("cs360_theme")||"dark";setupCatalog();init();
})();
